/**
 * QR Code Parser Utility
 * Parses QR codes generated by MachineCare Hub webapp (/m/:id)
 * as well as raw UUIDs, chassis numbers, and vehicle registration plates.
 */

export interface ParsedQrResult {
  type: "uuid" | "search";
  value: string;
  driverId?: string;
  rawInput: string;
}

export function parseVehicleQrOrInput(input: string): ParsedQrResult {
  const clean = (input || "").trim();

  // 1. Check for MachineCare webapp URL format: .../m/<uuid>?driver=<driverId>
  const urlMatch = clean.match(/\/m\/([0-9a-fA-F-]{36})/i);
  if (urlMatch) {
    const uuid = urlMatch[1];
    const driverMatch = clean.match(/[?&]driver=([^&#]+)/i);
    return {
      type: "uuid",
      value: uuid,
      driverId: driverMatch ? decodeURIComponent(driverMatch[1]) : undefined,
      rawInput: clean,
    };
  }

  // 2. Check for pure UUID (36 chars)
  const uuidRegex = /^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$/;
  if (uuidRegex.test(clean)) {
    return {
      type: "uuid",
      value: clean,
      rawInput: clean,
    };
  }

  // 3. Fallback to plate / registration search
  return {
    type: "search",
    value: clean,
    rawInput: clean,
  };
}
